mapper.select:
select count(*) from wiki_chat_session
where session_id = #{sessionId} and created_by = #{username}
  and scope_type = 'DATA_QUERY' and scope_id = #{proposalId}

select session_id, title, update_time from wiki_chat_session
where created_by = #{username} and scope_type = 'DATA_QUERY' and scope_id = #{proposalId}
order by update_time desc, session_id desc
limit #{limit} offset #{offset}

select message.message_id, message.content, message.create_time
from wiki_chat_message message
inner join wiki_chat_session session on session.session_id = message.session_id
    and session.created_by = message.created_by
where message.session_id = #{sessionId} and message.created_by = #{username}
  and session.scope_type = 'DATA_QUERY' and session.scope_id = #{proposalId}
  and message.role = 'assistant' and message.message_id < #{beforeId}
order by message.message_id desc
limit #{limit}

mapper.update:
update wiki_chat_session set update_time = current_timestamp
where session_id = #{sessionId} and created_by = #{username}
  and scope_type = 'DATA_QUERY' and scope_id = #{proposalId}
